    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    holes = {}
    for r, row in enumerate(grid):
        for c in range(1, w - 1):
            color = row[c - 1]
            if color and row[c] == 0 and row[c + 1] == color:
                holes.setdefault(c, []).append((r, color))
    for c, events in holes.items():
        events.sort()
